const palette = ['blue', 'green', 'purple', 'gold'];
export const lessons = Object.fromEntries(topics.map(([id, title, summary, names, ...steps]) => [
  id, {
    id, title, summary, minutes: steps.length * 2, difficulty: 'Foundations',
    nodes: names.map((name, i) => ({ id: `n${i}`, name, kind: i === 0 ? 'people' : /store|database|table|disk|SQL|log|storage/i.test(name) ? 'database' : 'server', color: palette[i] })),
    steps: steps.map(([title, body, idea], i) => ({
      label: title, title, body: [body], idea, tag: i === 0 ? 'Setup' : i === steps.length - 1 ? 'Recap' : 'Explore',
      visible: names.slice(0, Math.min(i + 2, names.length)).map((_, n) => `n${n}`),
      edges: Array.from({ length: Math.min(i + 1, names.length - 1) }, (_, n) => [`n${n}`, `n${n + 1}`, n === 0 ? 'request' : 'data']),
      change: i === 0 ? 'Start with the first request path.' : `Explore ${title.toLowerCase()} in the system.`,
    })),
    goals: steps.map(([title]) => title),
  },
]));

